git checkout -b fix/7-refresh-recursion && cat > src/auth.js <<'EOF'
// Refreshes the session when its cookie expired.
// fetchSession is supplied by the caller and returns a new session.
export function refresh(session, fetchSession) {
  if (session.expired) return fetchSession();
  return session;
}
EOF
